import java.util.*;
public class Main {
    static class Point {
        int x, y;
        Point(int x, int y) { this.x = x; this.y = y; }
        @Override public boolean equals(Object o) {
            return o instanceof Point p && p.x == x && p.y == y;
        }
        @Override public int hashCode() { return 31 * x + y; }
    }
    public static void main(String[] args) {
        Set<Point> s = new HashSet<>();
        s.add(new Point(1, 1));
        s.add(new Point(1, 1));
        System.out.println("size=" + s.size());
    }
}

import java.util.*;
public class Main {
    public static int[] twoSum(int[] nums, int target) {
        Map<Integer, Integer> idx = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            if (idx.containsKey(target - nums[i])) return new int[]{idx.get(target - nums[i]), i};
            idx.put(nums[i], i);
        }
        return new int[]{};
    }
    public static void main(String[] args) {
        int[] r = twoSum(new int[]{2, 7, 11, 15}, 9);
        System.out.println(r[0] + "," + r[1]);
    }
}

import java.util.*;
public class Main {
    public static List<List<String>> groupAnagrams(String[] strs) {
        Map<String, List<String>> m = new HashMap<>();
        for (String s : strs) {
            char[] c = s.toCharArray();
            Arrays.sort(c);
            String key = new String(c);
            m.computeIfAbsent(key, k -> new ArrayList<>()).add(s);
        }
        List<List<String>> res = new ArrayList<>(m.values());
        for (List<String> g : res) Collections.sort(g);
        res.sort((a, b) -> a.get(0).compareTo(b.get(0)));
        return res;
    }
    public static void main(String[] args) {
        System.out.println(groupAnagrams(new String[]{"eat", "tea", "tan", "ate", "nat", "bat"}));
    }
}

import java.util.*;
public class Main {
    public static int[] topKFrequent(int[] nums, int k) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int n : nums) freq.put(n, freq.getOrDefault(n, 0) + 1);
        List<int[]> list = new ArrayList<>();
        for (Map.Entry<Integer, Integer> e : freq.entrySet()) list.add(new int[]{e.getKey(), e.getValue()});
        list.sort((a, b) -> b[1] - a[1]);
        int[] res = new int[k];
        for (int i = 0; i < k; i++) res[i] = list.get(i)[0];
        return res;
    }
    public static void main(String[] args) {
        System.out.println(Arrays.toString(topKFrequent(new int[]{1, 1, 1, 2, 2, 3}, 2)));
    }
}
